// Timeout-bounded probe shape (async version uses reqwest + tokio::time).
pub struct ProbeResult {
    pub url: String,
    pub ok: bool,
    pub elapsed_ms: u128,
}

pub fn evaluate(url: &str, latency_ms: u64, cap_ms: u64) -> ProbeResult {
    ProbeResult {
        ok: latency_ms <= cap_ms && !url.is_empty(),
        url: url.to_string(),
        elapsed_ms: latency_ms as u128,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn flags_slow_probes() {
        assert!(!evaluate("http://x", 6000, 5000).ok);
        assert!(evaluate("http://x", 40, 5000).ok);
    }
}
